*, *::before, *::after { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--text); font-family: var(--font-body); overflow-x: hidden; }
.page { max-width: 1120px; margin: 0 auto; padding: var(--space-8) var(--space-6); display: grid; gap: var(--space-6); min-width: 0; }
.page-head { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-4); }
.page-head h1 { margin: 0; font: 700 1.75rem/1.3 var(--font-body); }
.toolbar { display: flex; flex-wrap: wrap; gap: var(--space-4); align-items: flex-start; }
.toolbar > * { flex: 1 1 14rem; min-width: 0; }
.panel { min-width: 0; }
.panel > * { min-width: 0; }
.table-card { border: var(--border-width) solid var(--border); border-radius: var(--radius-card); background: var(--surface); padding: var(--card-padding); min-width: 0; }
.table-card .luca-table caption { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
.table-card .luca-table th, .table-card .luca-table td { vertical-align: middle; }
.table-card .luca-table th { color: var(--text); }
.num { text-align: right !important; font-variant-numeric: tabular-nums; }
.actions { display: flex; gap: var(--space-2); flex-wrap: wrap; justify-content: flex-end; }
.actions .luca-button { min-height: 2.25rem; padding: var(--space-1) var(--space-4); }
.badge { display: inline-block; padding: 0 var(--space-3); border: 1px solid currentColor; border-radius: 999px; font: 500 .8125rem/1.6 var(--font-body); white-space: nowrap; }
.badge-pending { color: var(--warning); }
.badge-paid { color: var(--accent-hover); }
.badge-shipped { color: var(--success); }
.badge-cancelled { color: var(--muted); }
.msg { margin: 0; color: var(--muted); }
.notice { padding: var(--space-6) 0; text-align: center; color: var(--muted); }
.stack { display: grid; gap: var(--space-4); }
.backdrop { position: fixed; inset: 0; background: rgba(0,0,0,.5); display: flex; align-items: center; justify-content: center; padding: var(--space-4); z-index: 10; overflow-y: auto; }
.dialog { width: 100%; max-width: 28rem; max-height: 100%; overflow-y: auto; background: var(--surface); color: var(--text); border: var(--border-width) solid var(--border); border-radius: var(--radius-card); padding: var(--space-6); display: grid; gap: var(--space-4); }
.dialog h2 { margin: 0; font: 600 1.25rem/1.4 var(--font-body); }
.dialog p { margin: 0; }
.dialog-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); justify-content: flex-end; }
.luca-field-error { color: var(--error); }

@media (max-width: 720px) {
  .page { padding: var(--space-4); }
  .page-head h1 { font-size: 1.5rem; }
  .table-card { padding: var(--space-2); }
  .table-card .luca-table thead { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); }
  .table-card .luca-table, .table-card .luca-table tbody, .table-card .luca-table tr, .table-card .luca-table td { display: block; width: 100%; }
  .table-card .luca-table tr { padding: var(--space-3) var(--space-2); border-bottom: 1px solid var(--border); }
  .table-card .luca-table td { display: flex; justify-content: space-between; align-items: center; gap: var(--space-4); border: 0; padding: var(--space-1) var(--space-2); text-align: right; }
  .table-card .luca-table td::before { content: attr(data-label); color: var(--muted); text-align: left; flex-shrink: 0; }
  .table-card .luca-table td.num { text-align: right !important; }
  .table-card .luca-table td.cell-actions::before { content: none; }
  .actions { width: 100%; justify-content: flex-end; }
}

